ops:
  '待確認': ['類型', '說明', '日期', '工程名稱', '項目', '單位', '來源', '案件編號', '確認者', '確認時間', '處理說明'],
  reviewConfirm: [apiReviewConfirm, ['系統維護']],
const REVIEW_COLS = ['確認者', '確認時間', '處理說明'];
/** 搬遷待確認清單（含確認狀態；_row 供確認時定位） */
function apiReview() {
  ensureCols_('待確認', REVIEW_COLS);
  return readTable_('待確認').map(r => Object.assign(clean_(r), { _row: r._row }));
}
/** 標記已確認／取消確認：args = {row, name, note, undo} */
function apiReviewConfirm(args, user) {
  ensureCols_('待確認', REVIEW_COLS);
  const r = readTable_('待確認').find(x => x._row === +args.row && String(x.工程名稱) === String(args.name || ''));
  if (!r) throw new Error('找不到此待確認項目，請重新整理清單');
  if (args.undo) { r.確認者 = ''; r.確認時間 = ''; r.處理說明 = ''; }
  else { r.確認者 = user.Email; r.確認時間 = nowStr_(); r.處理說明 = String(args.note || '').trim() || '已確認，維持現狀'; }
  writeRow_('待確認', r);
  log_(user.Email, args.undo ? '取消確認搬遷待確認' : '確認搬遷待確認', r.案件編號 || '', { 類型: r.類型, 工程名稱: r.工程名稱, 日期: r.日期, 處理說明: r.處理說明 });
  return Object.assign(clean_(r), { _row: r._row });
}
